import{_ as e,o as a,c as o,aj as d}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Expression Syntax","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/templates/expression-syntax.md","filePath":"en/guide/templates/expression-syntax.md"}'),r={name:"en/guide/templates/expression-syntax.md"};function s(n,t,i,l,c,p){return a(),o("div",null,t[0]||(t[0]=[d('<h1 id="expression-syntax" tabindex="-1">Expression Syntax <a class="header-anchor" href="#expression-syntax" aria-label="Permalink to &quot;Expression Syntax&quot;">​</a></h1><p>Angular expressions are based on JavaScript, but differ in some key ways. This guide walks through the similarities and differences between Angular expressions and standard JavaScript.</p><h2 id="value-literals" tabindex="-1">Value literals <a class="header-anchor" href="#value-literals" aria-label="Permalink to &quot;Value literals&quot;">​</a></h2><p>Angular supports a subset of <a href="https://developer.mozilla.org/en-US/docs/Glossary/Literal" target="_blank" rel="noreferrer">literal values</a> from JavaScript.</p><h3 id="supported-value-literals" tabindex="-1">Supported value literals <a class="header-anchor" href="#supported-value-literals" aria-label="Permalink to &quot;Supported value literals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Literal type</th><th>Example values</th></tr></thead><tbody><tr><td>String</td><td><code>&#39;Hello&#39;</code>, <code>&quot;World&quot;</code></td></tr><tr><td>Boolean</td><td><code>true</code>, <code>false</code></td></tr><tr><td>Number</td><td><code>123</code>, <code>3.14</code></td></tr><tr><td>Object</td><td><code>{name: &#39;Alice&#39;}</code></td></tr><tr><td>Array</td><td><code>[&#39;Onion&#39;, &#39;Cheese&#39;, &#39;Garlic&#39;]</code></td></tr><tr><td>null</td><td><code>null</code></td></tr><tr><td>RegExp</td><td><code>/\\d+/</code></td></tr><tr><td>Template string</td><td><code>`Hello ${name}`</code></td></tr><tr><td>Tagged template string</td><td><code>tag`Hello ${name}`</code></td></tr></tbody></table><h3 id="unsupported-value-literals" tabindex="-1">Unsupported value literals <a class="header-anchor" href="#unsupported-value-literals" aria-label="Permalink to &quot;Unsupported value literals&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Literal type</th><th>Example values</th></tr></thead><tbody><tr><td>BigInt</td><td><code>1n</code></td></tr></tbody></table><h2 id="globals" tabindex="-1">Globals <a class="header-anchor" href="#globals" aria-label="Permalink to &quot;Globals&quot;">​</a></h2><p>Angular expressions support the following <a href="https://developer.mozilla.org/en-US/docs/Glossary/Global_object" target="_blank" rel="noreferrer">globals</a>:</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/undefined" target="_blank" rel="noreferrer">undefined</a></li><li><a href="https://www.typescriptlang.org/docs/handbook/2/everyday-types.html#any" target="_blank" rel="noreferrer">$any</a></li></ul><p>No other JavaScript globals are supported. Common JavaScript globals include <code>Number</code>, <code>Boolean</code>, <code>NaN</code>, <code>Infinity</code>, <code>parseInt</code>, and more.</p><h2 id="local-variables" tabindex="-1">Local variables <a class="header-anchor" href="#local-variables" aria-label="Permalink to &quot;Local variables&quot;">​</a></h2><p>Angular automatically makes special local variables available for use in expressions in specific contexts. These special variables always start with the dollar sign character (<code>$</code>).</p><p>For example, <code>@for</code> blocks make several local variables corresponding to information about the loop, such as <code>$index</code>.</p><h2 id="what-operators-are-supported" tabindex="-1">What operators are supported? <a class="header-anchor" href="#what-operators-are-supported" aria-label="Permalink to &quot;What operators are supported?&quot;">​</a></h2><h3 id="supported-operators" tabindex="-1">Supported operators <a class="header-anchor" href="#supported-operators" aria-label="Permalink to &quot;Supported operators&quot;">​</a></h3><p>Angular supports the following operators from standard JavaScript.</p><table tabindex="0"><thead><tr><th>Operator</th><th>Example(s)</th></tr></thead><tbody><tr><td>Add / Concatenate</td><td><code>1 + 2</code></td></tr><tr><td>Subtract</td><td><code>52 - 3</code></td></tr><tr><td>Multiply</td><td><code>41 * 6</code></td></tr><tr><td>Divide</td><td><code>20 / 4</code></td></tr><tr><td>Remainder (Modulo)</td><td><code>17 % 5</code></td></tr><tr><td>Exponentiation</td><td><code>10 ** 3</code></td></tr><tr><td>Parenthesis</td><td><code>9 * (8 + 4)</code></td></tr><tr><td>Conditional (Ternary)</td><td><code>a &gt; b ? true : false</code></td></tr><tr><td>And (Logical)</td><td><code>&amp;&amp;</code></td></tr><tr><td>Or (Logical)</td><td><code>||</code></td></tr><tr><td>Not (Logical)</td><td><code>!</code></td></tr><tr><td>Nullish Coalescing</td><td><code>possiblyNullValue ?? &#39;default&#39;</code></td></tr><tr><td>Comparison Operators</td><td><code>&lt;</code>, <code>&lt;=</code>, <code>&gt;</code>, <code>&gt;=</code>, <code>==</code>, <code>===</code>, <code>!==</code>, <code>!=</code></td></tr><tr><td>Unary Negation</td><td><code>-x</code></td></tr><tr><td>Unary Plus</td><td><code>+y</code></td></tr><tr><td>Property Accessor</td><td><code>person[&#39;name&#39;]</code></td></tr><tr><td>typeof</td><td><code>typeof 42</code></td></tr><tr><td>void</td><td><code>void 1</code></td></tr><tr><td>in</td><td><code>&#39;model&#39; in car</code></td></tr><tr><td>instanceof</td><td><code>car instanceof Automobile</code></td></tr><tr><td>Assignment</td><td><code>a = b</code></td></tr><tr><td>Increment</td><td><code>a++</code>, <code>++a</code></td></tr><tr><td>Decrement</td><td><code>a--</code>, <code>--a</code></td></tr><tr><td>Addition Assignment</td><td><code>a += b</code></td></tr><tr><td>Subtraction Assignment</td><td><code>a -= b</code></td></tr><tr><td>Multiplication Assignment</td><td><code>a *= b</code></td></tr><tr><td>Division Assignment</td><td><code>a /= b</code></td></tr><tr><td>Remainder Assignment</td><td><code>a %= b</code></td></tr><tr><td>Exponentiation Assignment</td><td><code>a **= b</code></td></tr><tr><td>Logical AND Assignment</td><td><code>a &amp;&amp;= b</code></td></tr><tr><td>Logical OR Assignment</td><td><code>a ||= b</code></td></tr><tr><td>Nullish Coalescing Assignment</td><td><code>a ??= b</code></td></tr><tr><td>Spread in object literals</td><td><code>{...obj, foo: &#39;bar&#39;}</code></td></tr><tr><td>Spread in array literals</td><td><code>[...arr, 1, 2, 3]</code></td></tr><tr><td>Rest in function calls</td><td><code>fn(...args)</code></td></tr><tr><td>Arrow function</td><td><code>items.filter((i) =&gt; i.active)</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Assignment and increment/decrement operators are only valid in <a href="#event-listener-statements">event listener statements</a>. Using them in a binding or interpolation is a compile error, unless they are inside an arrow function.</p></div><p>Arrow functions must have an expression body. Pipes cannot be used inside an arrow function, but you can pass an arrow function as an argument to a pipe.</p><p>Angular expressions additionally also support the following non-standard operators:</p><table tabindex="0"><thead><tr><th>Operator</th><th>Example(s)</th></tr></thead><tbody><tr><td><a href="/en/guide/templates/pipes">Pipe</a></td><td><code>{{ total | currency }}</code></td></tr><tr><td>Optional chaining*</td><td><code>someObj.someProp?.nestedProp</code></td></tr><tr><td>Non-null assertion (TypeScript)</td><td><code>someObj!.someProp</code></td></tr></tbody></table><h3 id="safe-navigation-migration" tabindex="-1">Safe navigation migration <a class="header-anchor" href="#safe-navigation-migration" aria-label="Permalink to &quot;Safe navigation migration&quot;">​</a></h3><p>Prior to Angular 22, the optional chaining operator (<code>?.</code>) returned <code>null</code> when the left-hand side is <code>null</code> or <code>undefined</code>, whereas standard JavaScript&#39;s <code>?.</code> returns <code>undefined</code>. Since Angular 22, the optional chaining operator behavior in Angular expressions is aligned with the standard JavaScript behavior.</p><p>During the migration to v22, the <code>ng update</code> schematics adds a <code>$safeNavigationMigration</code> function to existing expressions to preserve the previous behavior.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ $safeNavigationMigration(foo?.bar) }}</span></span></code></pre></div><p><code>$safeNavigationMigration</code> is a <strong>temporary migration aid only</strong>. It instructs the compiler to compile the wrapped safe-navigation expression using the legacy null-returning semantics rather than the standard JavaScript <code>?.</code> semantics. It is not a real function and cannot be called from TypeScript.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Prefer migrating expressions to no longer rely on <code>null</code> vs <code>undefined</code> distinctions so that <code>$safeNavigationMigration</code> can be removed. This function may be removed in a future version of Angular.</p></div><h3 id="unsupported-operators" tabindex="-1">Unsupported operators <a class="header-anchor" href="#unsupported-operators" aria-label="Permalink to &quot;Unsupported operators&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Example(s)</th></tr></thead><tbody><tr><td>All bitwise operators</td><td><code>&amp;</code>, <code>&amp;=</code>, <code>~</code>, <code>|=</code>, <code>^=</code>, etc.</td></tr><tr><td>Object destructuring</td><td><code>const { name } = person</code></td></tr><tr><td>Array destructuring</td><td><code>const [firstItem] = items</code></td></tr><tr><td>Comma operator</td><td><code>x = (x++, x)</code></td></tr><tr><td>new</td><td><code>new Car()</code></td></tr></tbody></table><h2 id="lexical-context-for-expressions" tabindex="-1">Lexical context for expressions <a class="header-anchor" href="#lexical-context-for-expressions" aria-label="Permalink to &quot;Lexical context for expressions&quot;">​</a></h2><p>Angular expressions are evaluated within the context of the component class as well as any relevant <a href="/en/guide/templates/variables">template variables</a>, locals, and globals.</p><p>When referring to component class members, <code>this</code> is always implied. However, if a template declares a <a href="/en/guide/templates/variables">template variables</a> with the same name as a member, the variable shadows that member. You can unambiguously reference such a class member by explicitly using <code>this.</code>. This can be useful when creating an <code>@let</code> declaration that shadows a class member, e.g. for signal narrowing purposes.</p><h2 id="declarations" tabindex="-1">Declarations <a class="header-anchor" href="#declarations" aria-label="Permalink to &quot;Declarations&quot;">​</a></h2><p>Generally speaking, declarations are not supported in Angular expressions. This includes, but is not limited to:</p><table tabindex="0"><thead><tr><th>Declarations</th><th>Example(s)</th></tr></thead><tbody><tr><td>Variables</td><td><code>let label = &#39;abc&#39;</code>, <code>const item = &#39;apple&#39;</code></td></tr><tr><td>Functions</td><td><code>function myCustomFunction() { }</code></td></tr><tr><td>Arrow functions with block bodies</td><td><code>() =&gt; { }</code></td></tr><tr><td>Classes</td><td><code>class Rectangle { }</code></td></tr></tbody></table><h2 id="event-listener-statements" tabindex="-1">Event listener statements <a class="header-anchor" href="#event-listener-statements" aria-label="Permalink to &quot;Event listener statements&quot;">​</a></h2><p>Event handlers are <strong>statements</strong> rather than expressions. While they support all of the same syntax as Angular expressions, there are two key differences:</p><ol><li>Statements <strong>do support</strong> assignment operators (but not destructuring assignments)</li><li>Statements <strong>do not support</strong> pipes</li></ol>',40)]))}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
